head.script:
scwin.dataListId = "dataList1";
scwin.dataListId2 = "dataList2";
scwin.gridViewId = "gridView1";
scwin.gridViewId2 = "gridView2";
scwin.extraColNum = 5 + 6;
scwin.extraColNum2 = 5;
scwin.oneDayCol = ['pdiaDvChar', 'ndDno', 'totWrkTnum', 'pdiaNoView', 'repTrn1No', 'repTrn2No', 'pjt2PdiaNo', 'gwkTm', 'loiwTm']


scwin.onpageload = function() {
    scwin.createDataList1();
    scwin.createDataList2();
    scwin.loadData();
    scwin.createGridView1_detail();
    scwin.createGridView2_detail();
};

scwin.createDataList1 = function() {
    if ($p.getComponentById(scwin.dataListId)) {
        $p.data.remove(scwin.dataListId);
    }
    var dayCnt = scwin.getDaysInCurrentMonth();
    var colInfo = [{
        "dataType": "text",
        "id": "diaPosiCd"
    }, {
        "dataType": "text",
        "id": "empNm"
    }, {
        "dataType": "text",
        "id": "epno"
    }, {
        "dataType": "number",
        "id": "holidayGwkTm"
    }, {
        "dataType": "number",
        "id": "totalGwkTm"
    }, {
        "dataType": "text",
        "id": "b_dynamic2"
    }, {
        "dataType": "text",
        "id": "b_dynamic3"
    }, {
        "dataType": "text",
        "id": "b_dynamic4"
    }, {
        "dataType": "text",
        "id": "b_dynamic6"
    }, {
        "dataType": "text",
        "id": "b_dynamic7"
    }, {
        "dataType": "text",
        "id": "b_dynamic8"
    }];
    for (var i = 1; i <= dayCnt; i++) {
        for (var j = 0; j < scwin.oneDayCol.length; j++) {
            colInfo.push({
                "dataType": "text",
                "id": i + "_" + scwin.oneDayCol[j]
            })
        }
    }
    var opt = {
        "type": "dataList",
        "id": scwin.dataListId,
        "option": {
            "baseNode": "list",
            "repeatNode": "map"
        },
        "columnInfo": colInfo
    };
    $p.data.create(opt);
}

scwin.createDataList2 = function() {
    if ($p.getComponentById(scwin.dataListId2)) {
