scwin.loadData = function() {
    var url = WebSquare.core.getURL("gridView_SRT_dragdrop_WAEA-412_(WSQ-6080).txt");
    fetch(url).then(function(resolve, reject) {
        return resolve.text();
    }).then(function(resolve, reject) {
        var dataArr = JSON.parse(resolve);
        var dataListObj = $p.getComponentById(scwin.dataListId);
        dataListObj.setData(dataArr);

        var dataListObj2 = $p.getComponentById(scwin.dataListId2);
        var rowCnt = dataListObj.getRowCount();
        dataListObj2.setBroadcast(false);
        for (var i = 0; i < rowCnt; i++) {
            dataListObj2.insertRow();
        }
        dataListObj2.setBroadcast(true, true);
    })
}

scwin.getCommonGridOptions = function() {
    return ' rowNumVisible="true" rowNumHeaderValue="No." rowMouseOver="false" drawTypeX="hybrid" fixedColumnScrollHidden="true" fixedColumnNoMove="true" useShiftKey="true" ctrlShiftKey="true" oddEvenColorDisplay="false" focusMerge="true" dataDragDropCell="true" dataDragScrollFix="true" showLastRow="true" '
}

scwin.createGridView1_detail = function() {
    var dataListObj = $p.getComponentById(scwin.dataListId);
    var row = 72;
    var col = dataListObj.getColumnCount();
    var totalCol = col - scwin.extraColNum;
    var totalHeaderCol = totalCol / scwin.oneDayCol.length;
    var oneBodyCol = totalHeaderCol * 3;
    var gridColWidth = 70;
    var dayStyle = "";
    var gridXML = [];
    gridXML.push('<w2:gridView xmlns="http://www.w3.org/1999/xhtml" xmlns:w2="http://www.inswave.com/websquare" xmlns:ev="http://www.w3.org/2001/xml-events" id="' + "gridView1" + '" rowNumWidth="60" style="height:429px;" dataList="data:dataList1" fixedColumn="1" fixedRightColumn="2" readOnly="true" contextMenu="true" focusMergeUnit="3,3" dragEndFunction="scwin.gridView1_dragEndFunction" ev:ondatadragstart="scwin.gridView1_ondatadragstart" ev:onscrollx="scwin.gridView1_onscrollx" ev:onscrolly="scwin.gridView1_onscrolly"' + scwin.getCommonGridOptions() + '>');
    gridXML.push('<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>');
    gridXML.push('<w2:header style="background-color:#e4e7eb;" id="header1">');
    gridXML.push('<w2:row style="" id="row1">');
    gridXML.push('<w2:column width="70" fixColumnWidth="true" inputType="text" style="background-color:#e4e7eb;" id="columnEmpInfo" value="승무원"/>');
    for (var i = 0; i < totalHeaderCol; i++) {
        gridXML.push('<w2:column width="' + gridColWidth + '" inputType="text" style="background-color:#e4e7eb;' + dayStyle + '" id="column' + i + '" value="' + (i + 1) + '" displayMode="label" colSpan="3"/>');
    }
    gridXML.push('<w2:column width="70" inputType="text" style="background-color:#e4e7eb;" id="columnOffdDdFlg" value="휴일" displayMode="label" />');
    gridXML.push('<w2:column width="70" inputType="text" style="background-color:#e4e7eb;" id="columnGwkTm" value="근무시간" displayMode="label" />');
    gridXML.push('</w2:row>');
    gridXML.push('</w2:header>');
    gridXML.push('<w2:gBody style="" id="gBody1">');
    gridXML.push('<w2:row style="" id="rowB1">');
    gridXML.push('<w2:column width="70" inputType="text" style="" id="epno" value="" displayMode="label"></w2:column>');
    for (var i = 0; i < oneBodyCol; i++) {
        var idx = scwin.oneDayCol.length * Math.floor(i / 3) + (i % 3);
        var dateKey = dataListObj.getColumnID(idx + scwin.extraColNum);
        gridXML.push('<w2:column width="' + gridColWidth + '" inputType="text" style="" id="' + dateKey + '" value="" displayMode="label"/>');
    }
    gridXML.push('<w2:column rowSpan="3" width="70" inputType="text" style="background-color : #ADD8E6;" id="holidayGwkTm" displayMode="label"></w2:column>');
    gridXML.push('<w2:column rowSpan="3" width="70" inputType="text" style="background-color : #ADD8E6;" id="totalGwkTm" value="" displayMode="label" customFormatter="scwin.customFormatterTotalGwkTm"></w2:column>');
    gridXML.push('</w2:row>');
    gridXML.push('<w2:row style="" id="rowB2">');
    gridXML.push('<w2:column width="70" inputType="text" style="" id="empNm" value="" displayMode="label"></w2:column>');
    for (var i = 0; i < oneBodyCol; i++) {
        var idx = scwin.oneDayCol.length * Math.floor(i / 3) + (i % 3) + 3;
        var dateKey = dataListObj.getColumnID(idx + scwin.extraColNum);
        gridXML.push('<w2:column width="' + gridColWidth + '" inputType="text" style="" id="' + dateKey + '" value="" displayMode="label"/>');
    }
    gridXML.push('</w2:row>');
    gridXML.push('<w2:row style="" id="rowB3">');
    gridXML.push('<w2:column width="70" inputType="text" style="" id="diaPosiCd" value="" displayMode="label"></w2:column>');
    for (var i = 0; i < oneBodyCol; i++) {
        var idx = scwin.oneDayCol.length * Math.floor(i / 3) + (i % 3) + 6;
        var dateKey = dataListObj.getColumnID(idx + scwin.extraColNum);
        gridXML.push('<w2:column width="' + gridColWidth + '" inputType="text" style="" id="' + dateKey + '" value="" displayMode="label"/>');
    }
    gridXML.push('</w2:row>');
    gridXML.push('</w2:gBody>');
    gridXML.push('<w2:footer id="footer1" style="">');
    gridXML.push('<w2:row id="row5" style="">');
    gridXML.push('<w2:column displayMode="label" id="ft1_epno" inputType="text" style="" value="" width="70"></w2:column>');
    for (var i = 0; i < totalHeaderCol; i++) {
        var dateKey = dataListObj.getColumnID((i * scwin.oneDayCol.length) + scwin.extraColNum);
        gridXML.push('<w2:column colSpan="3" width="' + gridColWidth + '" inputType="expression" style="" id="ft1_' + dateKey + '" value="" displayMode="label" expression="custom(scwin.gridView1_footerCustomFormatter, &quot;' + dateKey + '&quot;)"></w2:column>');
    }
    gridXML.push('<w2:column width="70" inputType="expression" style="" id="ft1_holidayGwkTm" value="" displayMode="label" rowSpan="2" expression="SUM(&quot;' + "holidayGwkTm" + '&quot;)"></w2:column>');
    gridXML.push('<w2:column width="70" inputType="expression" style="" id="ft1_totalGwkTm" value="" displayMode="label" rowSpan="2" expression="scwin.customFormatterTotalGwkTm(SUM(&quot;' + "totalGwkTm" + '&quot;))"></w2:column>');
    gridXML.push('</w2:row>');
    gridXML.push('<w2:row id="row6" style="">');
    gridXML.push('<w2:column displayMode="label" id="ft2_epno" inputType="text" style="" value="" width="70"></w2:column>');
    for (var i = 0; i < totalHeaderCol; i++) {
        var dateKey = dataListObj.getColumnID((i * scwin.oneDayCol.length) + scwin.extraColNum);
        gridXML.push('<w2:column colSpan="3" width="' + gridColWidth + '" inputType="expression" style="" id="ft2_' + dateKey + '" value="" displayMode="label" expression="custom(scwin.gridView1_footerCustomFormatter2, &quot;' + dateKey + '&quot;)"></w2:column>');
    }
    gridXML.push('</w2:row>');
    gridXML.push('</w2:footer>');
    gridXML.push('</w2:gridView>');
    var gridStr = gridXML.join(" ");
    gridView1.setGridStyle(gridStr);
}


