        gridXML.push('<w2:column width="' + gridColWidth + '" inputType="text" style="" id="' + dateKey + '" value="" displayMode="label"/>');
    }
    gridXML.push('</w2:row>');
    gridXML.push('<w2:row style="" id="rowB3">');
    for (var i = 0; i < oneBodyCol; i += 3) {
        var idx = scwin.oneDayCol.length * Math.floor(i / 3) + (i % 3) + 6;
        var dateKey = dataListObj.getColumnID(idx + scwin.extraColNum2);
        gridXML.push('<w2:column width="' + gridColWidth + '" inputType="text" style="" id="' + dateKey + '" value="" displayMode="label"/>');
    }
    gridXML.push('</w2:row>');
    gridXML.push('</w2:gBody>');
    gridXML.push('<w2:footer id="footer1" style="">');
    gridXML.push('<w2:row id="row5" style="">');
    for (var i = 0; i < totalHeaderCol; i++) {
        var dateKey = dataListObj.getColumnID((i * scwin.oneDayCol.length) + scwin.extraColNum2);
        gridXML.push('<w2:column width="' + gridColWidth + '" inputType="expression" style="" id="ft1_' + dateKey + '" value="" displayMode="label" expression="custom(scwin.gridView2_footerCustomFormatter, &quot;' + dateKey + '&quot;)"></w2:column>');
    }
    gridXML.push('</w2:row>');
    gridXML.push('<w2:row id="row6" style="">');
    for (var i = 0; i < totalHeaderCol; i++) {
        var dateKey = dataListObj.getColumnID((i * scwin.oneDayCol.length) + scwin.extraColNum2);
        gridXML.push('<w2:column width="' + gridColWidth + '" inputType="expression" style="" id="ft2_' + dateKey + '" value="" displayMode="label" expression="custom(scwin.gridView2_footerCustomFormatter2, &quot;' + dateKey + '&quot;)"></w2:column>');
    }
    gridXML.push('</w2:row>');
    gridXML.push('</w2:footer>');
    gridXML.push('</w2:gridView>');
    var gridStr = gridXML.join(" ");
    gridView2.setGridStyle(gridStr);
}




