scwin.footerCustomFormatter = function(dataList, colId) {
    try {
        var targetColId = colId.slice(0, colId.indexOf("_") + 1) + "ndDno";
        // colId.slice(0, colId.indexOf("_") + 1) 를 실행하면 각 column에서 날짜 부분만 가져온다. 
        // 여기에 "ndDno"을 더하면 "1_ndDno"와 같이 각 날짜의 ndDno 컬럼을 조회할 수 있다.
        var rowCnt = dataList.getRowCount();
        var count = 0;
        for (var i = 0; i < rowCnt; i++) {
            var ndDnoValue = Number(dataList.getCellData(i, targetColId));
            if (ndDnoValue > 0) {
                count++;
            }
        }
        return count;
    } catch (error) {
        return "";
    }
};

scwin.footerCustomFormatter2 = function(dataList, colId) {
    try {
        var targetColId = colId.slice(0, colId.indexOf("_") + 1) + "totWrkTnum";
        var rowCnt = dataList.getRowCount();
        var sum = 0;
        for (var i = 0; i < rowCnt; i++) {
            var totWrkTnumValue = Number(dataList.getCellData(i, targetColId));
            if (!isNaN(totWrkTnumValue)) {
                sum += totWrkTnumValue;
            }
        }
        return scwin.customFormatterTotalGwkTm(sum);
    } catch (error) {
        return "";
    }
};

scwin.gridView1_ondatadragstart = function(cellIndexArr) {
    // cellIdIndexArr에는 포커스된 모든 cell에 대한 정보가 array 형태로 담겨 있다.
    for (var i = 0; i < cellIndexArr.length; i++) {
        var info = cellIndexArr[i];
        var rowIndex = info.rowIndex;
        var colId = info.colId; // ["1_pdiaDvChar", "1_ndDno"] 와 같이 항상 날짜 + "_" + 세부컬럼명 형태로 구성됨
        if (colId.indexOf("pdiaNoView") >= 0) {
            var pdiaNoView = dataList1.getCellData(rowIndex, colId);
            if (pdiaNoView == "S" || pdiaNoView == "~" || pdiaNoView == "X") {
                return false;
            }
        }
    }
    return true;
}

scwin.gridView1_dragEndFunction = function(toRowIndex, fromRowIndex, info) {
    if (!info) {
        return false;
    }
    // info.fromColumnId는 "1_pdiaDvChar" 형태 이므로 "_" 앞부분을 자르면 날짜를 가져올 수 있다.
    // 가져온 날짜에 "_" + ['pdiaDvChar', 'ndDno', 'totWrkTnum', 'pdiaNoView', 'repTrn1No', 'repTrn2No', 'pjt2PdiaNo', 'gwkTm', 'loiwTm'] 중 하나를 더하면 해당 날짜에 해당하는 3x3 cell의 데이터를 모두 조회할 수 있다.
    var fromDate = Number(info.fromColumnId.slice(0, info.fromColumnId.indexOf("_")));
    var toDate = Number(info.toColumnId.slice(0, info.toColumnId.indexOf("_")));
    var rowDiff = toRowIndex - fromRowIndex;
    var colDiff = toDate - fromDate;
    var bSameGrid = info.fromGridViewId === info.toGridViewId;
    if (bSameGrid) {
        if (fromDate > toDate) {
            alert("이전일로는 이동이 되지 않습니다.");
            return false;
        }
        if (fromRowIndex === toRowIndex) {
            alert("같은 행은 이동이 되지 않습니다.");
            return false;
        }
    }
    var fromDataArr = info.cellDataArray;
    if (gridView1.options.focusMergeUnit === "3,1") {
        // 상세보기가 아닌 경우 3x1 데이터가 fromDataArr로 들어오므로 이를 기반으로 3x3 데이터를 얻는 처리를 해야 한다. 
        // 3x1 셀을 움직이더라도 실제 데이터는 3x3 만큼 교체되어야 하기 때문이다.
        var fromGrid = $p.getComponentById(info.fromGridViewId);
        fromDataArr = scwin.convertCellDataArray(fromDataArr, fromGrid._dataList);
        // scwin.convertCellDataArray 함수는 3x1 데이터를 기반으로 숨겨진 2개 컬럼의 데이터를 모두 찾아 3x3 데이터로 만드는 함수이다. 
    }
    var toDataArr = [];
    var invalidObj = {
        "S": true,
        "X": true,
        "~": true
    };
    for (var i = 0; i < fromDataArr.length; i++) {
        var toRowIndex = fromDataArr[i].rowIndex + rowDiff;
        var colIdx = fromDataArr[i].colId.indexOf("_");
        var fromColDate = colDiff + Number(fromDataArr[i].colId.slice(0, colIdx));
        var toColId = fromColDate + fromDataArr[i].colId.slice(colIdx);
        var fromData = fromDataArr[i].data;
        var toData = dataList1.getCellData(toRowIndex, toColId);
        if (bSameGrid && toColId.indexOf("pdiaNoView") >= 0) {
            if (invalidObj[toData] === true || invalidObj[fromData]) {
                alert("휴무일, 비번은 이동이 되지 않습니다.");
                return false;
            }
        }
        toDataArr.push({
            "fromRowIndex": fromDataArr[i].rowIndex,
            "fromColId": fromDataArr[i].colId,
            "toRowIndex": toRowIndex,
            "toColId": toColId,
            "fromData": fromData,
            "toData": toData
        });
    }
    if (bSameGrid) {
        gridView1.removeFocusedCell();
    } else {
        gridView2.removeFocusedCell();
    }
    var dayHash = {};
    for (var i = 0; i < toDataArr.length; i++) {
        if (bSameGrid) {
            dataList1.setCellData(toDataArr[i].toRowIndex, toDataArr[i].toColId, toDataArr[i].fromData);
            dataList1.setCellData(toDataArr[i].fromRowIndex, toDataArr[i].fromColId, toDataArr[i].toData);
            var colIdx = toDataArr[i].toColId.slice(0, toDataArr[i].toColId.indexOf("_"));
            if (!dayHash[colIdx]) {
                gridView1.setFocusedCell(toDataArr[i].toRowIndex, toDataArr[i].toColId, false, {"ctrled":true});
                dayHash[colIdx] = true;
            }
        } else {
            dataList1.setCellData(toDataArr[i].toRowIndex, toDataArr[i].toColId, toDataArr[i].fromData);
            dataList2.setCellData(toDataArr[i].fromRowIndex, toDataArr[i].fromColId, "");
        }
    }
    return false;
}



scwin.gridView2_dragEndFunction = function(toRowIndex, fromRowIndex, info) {
    if (!info) {
        return false;
    }
    var fromDate = Number(info.fromColumnId.slice(0, info.fromColumnId.indexOf("_")));
    var toDate = Number(info.toColumnId.slice(0, info.toColumnId.indexOf("_")));
    var rowDiff = toRowIndex - fromRowIndex;
    var colDiff = toDate - fromDate;
    var bSameGrid = info.fromGridViewId === info.toGridViewId;
    var fromDataArr = info.cellDataArray;
    if (gridView2.options.focusMergeUnit === "3,1") {
        // 상세보기가 아닌 경우 3x1 데이터가 들어오므로 3x3 데이터로 변환해야 한다.
        var fromGrid = $p.getComponentById(info.fromGridViewId);
        fromDataArr = scwin.convertCellDataArray(fromDataArr, fromGrid._dataList);
    }
    var toDataArr = [];
    var invalidObj = {
        "S": true,
        "X": true,
        "~": true
    };
    for (var i = 0; i < fromDataArr.length; i++) {
        var toRowIndex = fromDataArr[i].rowIndex + rowDiff;
        var colIdx = fromDataArr[i].colId.indexOf("_");
        var fromColDate = colDiff + Number(fromDataArr[i].colId.slice(0, colIdx));
        var toColId = fromColDate + fromDataArr[i].colId.slice(colIdx);
        var fromData = fromDataArr[i].data;
        var toData = dataList2.getCellData(toRowIndex, toColId);
        toDataArr.push({
            "fromRowIndex": fromDataArr[i].rowIndex,
            "fromColId": fromDataArr[i].colId,
            "toRowIndex": toRowIndex,
            "toColId": toColId,
            "fromData": fromData,
            "toData": toData
        });
    }
    if (bSameGrid) {
        gridView2.removeFocusedCell();
    } else {
        gridView1.removeFocusedCell();
    }
    var dayHash = {};
    for (var i = 0; i < toDataArr.length; i++) {
        if (bSameGrid) {
            dataList2.setCellData(toDataArr[i].toRowIndex, toDataArr[i].toColId, toDataArr[i].fromData);
            dataList2.setCellData(toDataArr[i].fromRowIndex, toDataArr[i].fromColId, toDataArr[i].toData);
            var colIdx = toDataArr[i].toColId.slice(0, toDataArr[i].toColId.indexOf("_"));
            if (!dayHash[colIdx]) {
                gridView2.setFocusedCell(toDataArr[i].toRowIndex, toDataArr[i].toColId, false, {"ctrled":true});
                dayHash[colIdx] = true;
            }
        } else {
            dataList2.setCellData(toDataArr[i].toRowIndex, toDataArr[i].toColId, toDataArr[i].fromData);
            dataList1.setCellData(toDataArr[i].fromRowIndex, toDataArr[i].fromColId, "");
        }
    }
    return false;
}


scwin.customFormatterTotalGwkTm = function(a, b, r, c) {
    try {
        var hours = Math.floor(a / 60);
        var minutes = a % 60;
        return `${hours}:${minutes.toString().padStart(2, '0')}`;
    } catch (e) {
        return "";
    }
};


//
// scroll sync
//

scwin.gridView1_onscrollx = function (e) {
    if ( gridView1.getUserData("stopScrollX") === true) {
        return;
        // gridView2의 가로 스크롤을 움직이는 경우 동기화를 위해 gridView1의 가로 스크롤을 움직이게 되는데, 그 경우에도 이 API가 호출된다. 이 경우에는 아무런 처리를 하지 않아야 한다. 그렇지 않으면 gridView2 동기화 처리로 인해 gridView1 스크롤이 움직이고, 움직인 만큼 다시 gridView2 동기화 처리가 일어나고, 거기에서 다시 gridView1 동기화 처리가 일어나는 무한 반복이 일어나게 된다.
    }
    gridView2.setUserData("stopScrollX", true);
    gridView2.setScrollLeft(gridView1.getScrollLeft());
    $p.setTimeout(function(){
        gridView2.setUserData("stopScrollX", false);
    }, {
        "delay" : 100
    });
};

scwin.gridView2_onscrollx = function (e) {
    if ( gridView2.getUserData("stopScrollX") === true) {
        return;
    }
    gridView1.setUserData("stopScrollX", true);
    gridView1.setScrollLeft(gridView2.getScrollLeft());
    $p.setTimeout(function(){
        gridView1.setUserData("stopScrollX", false);
    }, {
        "delay" : 100
    });
};

scwin.gridView2_onscrolly = function (e) {
    if ( gridView2.getUserData("stopScrollY") === true) {
        return;
    }
    gridView1.setUserData("stopScrollY", true);
    gridView1.setScrollTop(gridView2.getScrollTop());
    $p.setTimeout(function(){
        gridView1.setUserData("stopScrollY", false);
    }, {
        "delay" : 100
    });
};

scwin.gridView1_onscrolly = function (e) {
