scwin.checkbox1_onviewchange = function(info) {
    if (info.checked === true) {
        scwin.createGridView1_detail();
        scwin.createGridView2_detail();
    } else {
        scwin.createGridView1_simple();
        scwin.createGridView2_simple();
    }
}

scwin.convertCellDataArray = function(fromArr, dataList) {
    // 간단히 보기 상태에서 drag drop 시에도 3x3 단위로 데이터를 drag drop 하도록 처리하는 함수
    // 3x1 데이터의 정보를 토대로 감춰진 나머지 두 컬럼의 정보도 같이 얻는다.
    var ret = [];
    var hash = {};
    for (var i = 0; i < fromArr.length; i++) {
        var colId = fromArr[i].colId;
        var colIdx = colId.slice(0, colId.indexOf("_"));
        hash[fromArr[i].rowIndex + "_" + colIdx] = true;
    }
    for (var item in hash) {
        var info = item.split("_");
        var rowIndex = Number(info[0]);
        var colIdx = info[1];
        for (var j = 0; j < scwin.oneDayCol.length; j++) {
            var colId = colIdx + "_" + scwin.oneDayCol[j];
            ret.push({
                "rowIndex": rowIndex,
                "colId": colId,
                "data": dataList.getCellData(rowIndex, colId)
            })
        }
    }
    return ret;
}
